CREATE TABLE "household_calendar_tokens" (
	"household_id" uuid PRIMARY KEY NOT NULL,
	"token" text NOT NULL,
	"created_by" uuid DEFAULT app.current_user_id(),
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"rotated_at" timestamp with time zone,
	CONSTRAINT "household_calendar_tokens_token_unique" UNIQUE("token"),
	CONSTRAINT "household_calendar_tokens_token_check" CHECK (char_length("household_calendar_tokens"."token") between 32 and 64)
);
